import { describe, expect, test } from 'claude-code/testing'
import { EXCEPTIONS, FAMILIARITY, REPLACEMENTS } from '../hooks/data.ts'

// hooks/data.ts is generated by scripts/build_data.py. These tests pin what the checker relies on
// in it: the shape of each list and the choices the script makes. Each test was shown to fail when
// the step of the script it names is removed (the script was run, changed, into a scratch folder).

const famLines = FAMILIARITY.split('\n')
const fam = famLines.map(line => {
  const tab = line.indexOf('\t')
  return { line, word: line.slice(0, tab), rating: line.slice(tab + 1) }
})
const ratingOf = new Map(fam.map(f => [f.word, Number(f.rating)]))

type Replacement = { from: string; to: string[]; source: string; unless?: string }
const reps = JSON.parse(REPLACEMENTS) as Replacement[]
const rep = (from: string) => reps.find(r => r.from === from)

const exceptions = EXCEPTIONS.split('\n')
const SOURCES = ['plainlanguage.gov', '18F', 'GOV.UK', 'iso-24495']

describe('FAMILIARITY', () => {
  test('every line is one lower-case word: letters, with apostrophes only inside a word', () => {
    const bad = fam.filter(f => !/^\p{L}+(?:'\p{L}+)*$/u.test(f.word) || f.word !== f.word.toLowerCase())
    expect(bad.slice(0, 5).map(f => f.line)).toEqual([])
  })

  test("no form ending in 's is listed (a checker removes a final 's before looking a word up)", () => {
    expect(fam.filter(f => /'s$/.test(f.word)).slice(0, 5).map(f => f.line)).toEqual([])
  })

  test('every rating is between 1.0 and 7.0, with one decimal place', () => {
    const bad = fam.filter(f => !/^[1-7]\.\d$/.test(f.rating) || Number(f.rating) > 7)
    expect(bad.slice(0, 5).map(f => f.line)).toEqual([])
  })

  test('ratings are the precise values, not the whole-number ones', () => {
    // The source has a whole-number column (GPT_Fam_dominant) and a precise one (GPT_Fam_probs).
    const whole = fam.filter(f => f.rating.endsWith('.0')).length
    expect(whole).toBeLessThan(fam.length / 2)
  })

  test('each word is listed once', () => {
    const seen = new Set<string>()
    const twice = fam.filter(f => (seen.has(f.word) ? true : (seen.add(f.word), false)))
    expect(twice.map(f => f.line)).toEqual([])
  })

  test('each word carries its own rating: everyday words at or above the 6.0 cut-off, these terms below it', () => {
    const everyday = ['the', 'house', 'water', 'people', 'because', 'question', 'morning', 'children']
    const terms = ['repo', 'api', 'endpoint']
    expect(everyday.filter(w => !((ratingOf.get(w) ?? 0) >= 6.0))).toEqual([])
    expect(terms.filter(w => !((ratingOf.get(w) ?? 7) < 6.0))).toEqual([])
  })

  test('the whole list was built, not a part of it', () => {
    expect(fam.length).toBeGreaterThan(50_000)
  })
})

describe('REPLACEMENTS', () => {
  test('every entry is { from, to, source, unless? } and nothing else', () => {
    const bad = reps.filter(r => {
      const keys = Object.keys(r).sort().join(',')
      const okKeys = keys === 'from,source,to' || keys === 'from,source,to,unless'
      const okFrom = typeof r.from === 'string' && r.from !== '' && r.from === r.from.toLowerCase().trim()
      const okTo = Array.isArray(r.to) && r.to.every(t => typeof t === 'string' && t.trim() === t && t !== '')
      const okUnless = r.unless === undefined || (typeof r.unless === 'string' && r.unless !== '')
      return !(okKeys && okFrom && okTo && okUnless && typeof r.source === 'string')
    })
    expect(bad.slice(0, 5)).toEqual([])
  })

  test('each word or phrase has one entry', () => {
    const seen = new Set<string>()
    expect(reps.filter(r => (seen.has(r.from) ? true : (seen.add(r.from), false))).map(r => r.from)).toEqual([])
  })

  test('an entry names every source that lists it, and merges their replacements', () => {
    expect(rep('utilize')?.source).toBe('plainlanguage.gov, 18F, iso-24495')
    expect(rep('utilize')?.to).toEqual(['use'])
    expect(rep('initiate')?.source).toBe('plainlanguage.gov, 18F, GOV.UK')
    expect(rep('initiate')?.to).toEqual(['start', 'begin'])
  })

  test('only the four chosen sources are used, and each one contributes', () => {
    const named = new Set(reps.flatMap(r => r.source.split(', ')))
    expect([...named].sort()).toEqual([...SOURCES].sort())
  })

  test("replacements are read from each source's own format", () => {
    expect(rep('commence')?.to).toContain('begin') // plainlanguage.gov table
    expect(rep('execute')?.to).toEqual(['run', 'do']) // 18F: the words after "use"
    expect(rep('deploy')?.to).toContain('put into place') // GOV.UK: the words in quotation marks
    expect(rep('revert back')?.to).toEqual(['revert']) // iso-24495 DOUBLETS
    expect(rep('has the ability to')?.to).toEqual(['can']) // iso-24495 WORDY_PHRASES
  })

  test("the source's own 'unless' note is kept", () => {
    expect(rep('agenda')?.unless).toContain('meeting')
    expect(rep('foster')?.unless).toContain('children')
    expect(rep('combat')?.unless).toBe('military')
  })

  test('advice that is not a replacement is kept in round brackets', () => {
    expect(rep('transform')?.to).toEqual(["(describe what you're doing to change the thing)"])
    expect(rep('dialogue')?.to).toContain('(we speak to people)')
    expect(rep('in order to')?.to).toContain('(omit)')
  })

  test('the source lines the script changes are changed as recorded in data/NOTICE.md', () => {
    expect(rep('some')).toBeUndefined()
    expect(rep('said')).toBeUndefined()
    expect(rep('/')).toBeUndefined()
    expect(rep('not later than')?.to).toEqual(['by'])
    expect(rep('minimize')?.to).toEqual(['decrease'])
    expect(rep('time period')?.to).toEqual(['time', 'period'])
    expect(rep('and/or')?.to).toEqual(['a or b or both'])
    expect(rep('portal')?.unless).toBe('those words are in the name of the website or service')
    expect(rep('moving forward')?.to).toEqual(['from now on', 'in the future'])
    expect(rep('commit')?.to).toContain('plan to (verb)')
  })

  test('doublets with no plainer replacement in the source are left out', () => {
    expect(rep('terms and conditions')).toBeUndefined()
    expect(rep('cease and desist')).toBeUndefined()
    expect(rep('null and void')?.to).toEqual(['void'])
  })
})

describe('EXCEPTIONS', () => {
  test('one lower-case word per line, each once', () => {
    expect(exceptions.filter(w => !/^[a-z]+$/.test(w))).toEqual([])
    expect(new Set(exceptions).size).toBe(exceptions.length)
  })

  test('the examples the specification and the build brief name are exceptions', () => {
    const named = ['implement', 'execute', 'require', 'deploy', 'commit', 'instance', 'significant', 'interest', 'liability']
    expect(named.filter(w => !exceptions.includes(w))).toEqual([])
  })

  test('replacement-list words whose plain swap would damage technical writing are exceptions', () => {
    const damaging = ['parameters', 'delete', 'function', 'interface', 'address', 'request', 'option', 'type',
      'render', 'validate', 'terminate', 'implement', 'execute', 'require', 'deploy', 'commit']
    expect(damaging.filter(w => rep(w) === undefined)).toEqual([]) // each is on the replacement list
    expect(damaging.filter(w => !exceptions.includes(w))).toEqual([]) // and J07 is told to leave it
  })
})
